package com.erp.dao;

import com.erp.util.DBConnection;
import com.erp.util.PasswordUtil;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Admin account setup and parent-scoped family data. */
public class GuardianDAO {
    public List<Map<String,Object>> list()throws SQLException{return rows("SELECT u.id,u.name,u.email,u.status,g.phone,g.relationship_label,COUNT(gs.student_id) child_count FROM guardians g JOIN users u ON u.id=g.user_id LEFT JOIN guardian_student gs ON gs.guardian_id=g.id WHERE u.deleted_at IS NULL GROUP BY u.id,u.name,u.email,u.status,g.phone,g.relationship_label ORDER BY u.name");}
    public List<Map<String,Object>> studentOptions()throws SQLException{return rows("SELECT s.id,u.name,s.admission_no FROM students s JOIN users u ON u.id=s.user_id WHERE u.role='STUDENT' AND u.status=1 AND u.deleted_at IS NULL ORDER BY u.name");}
    public void create(String name,String email,String password,String phone,String relation,String[] studentIds)throws SQLException{
        try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{long userId;
            try(PreparedStatement p=c.prepareStatement("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'PARENT')",PreparedStatement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email);p.setString(3,PasswordUtil.sha256(password));p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){if(!k.next())throw new SQLException("Parent account could not be created.");userId=k.getLong(1);}}
            long guardianId;try(PreparedStatement p=c.prepareStatement("INSERT INTO guardians(user_id,phone,relationship_label) VALUES(?,?,?)",PreparedStatement.RETURN_GENERATED_KEYS)){p.setLong(1,userId);p.setString(2,phone.isBlank()?null:phone);p.setString(3,relation.isBlank()?null:relation);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){if(!k.next())throw new SQLException("Guardian profile could not be created.");guardianId=k.getLong(1);}}
            if(studentIds==null||studentIds.length==0)throw new SQLException("Link the parent account to at least one student.");
            try(PreparedStatement p=c.prepareStatement("INSERT INTO guardian_student(guardian_id,student_id,relationship_label) SELECT ?,s.id,? FROM students s JOIN users u ON u.id=s.user_id WHERE s.id=? AND u.role='STUDENT' AND u.deleted_at IS NULL")){for(String raw:studentIds){long id=Long.parseLong(raw);p.setLong(1,guardianId);p.setString(2,relation.isBlank()?null:relation);p.setLong(3,id);if(p.executeUpdate()!=1)throw new SQLException("One selected student is not available.");}}
            c.commit();
        }catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException("Parent account could not be created.",e);}}
    }
    public List<Map<String,Object>> children(long userId)throws SQLException{return rows("SELECT s.id student_id,u.name,s.admission_no,COALESCE(sc.roll_no,s.roll_no) roll_no,c.class_name,sec.section_name,sc.academic_year FROM guardians g JOIN guardian_student gs ON gs.guardian_id=g.id JOIN students s ON s.id=gs.student_id JOIN users u ON u.id=s.user_id LEFT JOIN student_class sc ON sc.id=(SELECT x.id FROM student_class x WHERE x.student_id=s.id ORDER BY x.academic_year DESC,x.id DESC LIMIT 1) LEFT JOIN sections sec ON sec.id=sc.section_id LEFT JOIN classes c ON c.id=sec.class_id WHERE g.user_id=? AND u.status=1 AND u.deleted_at IS NULL ORDER BY u.name",userId);}
    public Map<String,Object> child(long userId,long studentId)throws SQLException{return one("SELECT s.id student_id,u.name,s.admission_no,COALESCE(sc.roll_no,s.roll_no) roll_no,c.class_name,sec.section_name,sc.academic_year FROM guardians g JOIN guardian_student gs ON gs.guardian_id=g.id JOIN students s ON s.id=gs.student_id JOIN users u ON u.id=s.user_id LEFT JOIN student_class sc ON sc.id=(SELECT x.id FROM student_class x WHERE x.student_id=s.id ORDER BY x.academic_year DESC,x.id DESC LIMIT 1) LEFT JOIN sections sec ON sec.id=sc.section_id LEFT JOIN classes c ON c.id=sec.class_id WHERE g.user_id=? AND s.id=? AND u.status=1 AND u.deleted_at IS NULL",userId,studentId);}
    public List<Map<String,Object>> attendance(long userId,long studentId)throws SQLException{return rows("SELECT a.attendance_date,a.status,a.remarks,sub.subject_name FROM guardians g JOIN guardian_student gs ON gs.guardian_id=g.id JOIN attendance a ON a.student_id=gs.student_id JOIN subjects sub ON sub.id=a.subject_id WHERE g.user_id=? AND gs.student_id=? ORDER BY a.attendance_date DESC,a.id DESC LIMIT 30",userId,studentId);}
    public List<Map<String,Object>> assignments(long userId,long studentId)throws SQLException{return rows("SELECT a.id,a.title,a.due_date,sub.subject_name,x.submitted_at,CASE WHEN DATE(x.submitted_at)>a.due_date THEN 1 ELSE 0 END submitted_late,x.grade,x.feedback FROM guardians g JOIN guardian_student gs ON gs.guardian_id=g.id JOIN assignments a ON a.status=1 JOIN student_class sc ON sc.student_id=gs.student_id AND sc.section_id=a.section_id AND sc.academic_year=a.academic_year JOIN subjects sub ON sub.id=a.subject_id LEFT JOIN assignment_submissions x ON x.assignment_id=a.id AND x.student_id=gs.student_id WHERE g.user_id=? AND gs.student_id=? ORDER BY a.due_date",userId,studentId);}
    public List<Map<String,Object>> results(long userId,long studentId)throws SQLException{return rows("SELECT e.exam_name,e.exam_date,sub.subject_name,sub.max_marks,m.marks,m.remarks,(SELECT gs.grade_label FROM grade_scales gs WHERE gs.status=1 AND gs.min_percent<=100*m.marks/sub.max_marks ORDER BY gs.min_percent DESC LIMIT 1) grade FROM guardians g JOIN guardian_student gs ON gs.guardian_id=g.id JOIN marks m ON m.student_id=gs.student_id JOIN exams e ON e.id=m.exam_id AND e.results_published_at IS NOT NULL JOIN subjects sub ON sub.id=m.subject_id WHERE g.user_id=? AND gs.student_id=? ORDER BY e.exam_date DESC,e.exam_name",userId,studentId);}
    public List<Map<String,Object>> timetable(long userId,long studentId)throws SQLException{return rows("SELECT tt.day_of_week,tt.start_time,tt.end_time,tt.room,sub.subject_name,tu.name teacher_name FROM guardians g JOIN guardian_student gs ON gs.guardian_id=g.id JOIN student_class sc ON sc.student_id=gs.student_id JOIN timetable tt ON tt.section_id=sc.section_id AND tt.academic_year=sc.academic_year AND tt.status=1 JOIN subjects sub ON sub.id=tt.subject_id JOIN teachers t ON t.id=tt.teacher_id JOIN users tu ON tu.id=t.user_id WHERE g.user_id=? AND gs.student_id=? ORDER BY FIELD(tt.day_of_week,'MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'),tt.start_time",userId,studentId);}
    public List<Map<String,Object>> invoices(long userId,long studentId)throws SQLException{return rows("SELECT i.id,i.title,i.academic_year,i.amount,i.concession_amount,i.due_date,i.status,COALESCE(pt.paid,0)-COALESCE(rt.refunded,0) paid_amount,i.amount-i.concession_amount-COALESCE(pt.paid,0)+COALESCE(rt.refunded,0) balance,CASE WHEN i.amount-i.concession_amount-COALESCE(pt.paid,0)+COALESCE(rt.refunded,0)>0 AND i.due_date<CURRENT_DATE() THEN 1 ELSE 0 END overdue FROM guardians g JOIN guardian_student gs ON gs.guardian_id=g.id JOIN fee_invoices i ON i.student_id=gs.student_id LEFT JOIN (SELECT invoice_id,SUM(amount) paid FROM fee_payments GROUP BY invoice_id) pt ON pt.invoice_id=i.id LEFT JOIN (SELECT p.invoice_id,SUM(r.amount) refunded FROM fee_payments p JOIN fee_refunds r ON r.payment_id=p.id GROUP BY p.invoice_id) rt ON rt.invoice_id=i.id WHERE g.user_id=? AND gs.student_id=? ORDER BY i.due_date DESC",userId,studentId);}
    private List<Map<String,Object>> rows(String sql,Object... args)throws SQLException{List<Map<String,Object>> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){bind(p,args);try(ResultSet r=p.executeQuery()){int n=r.getMetaData().getColumnCount();while(r.next()){Map<String,Object> m=new LinkedHashMap<>();for(int i=1;i<=n;i++)m.put(r.getMetaData().getColumnLabel(i),r.getObject(i));out.add(m);}}}return out;}
    private Map<String,Object> one(String sql,Object... args)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){bind(p,args);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Map<String,Object> m=new LinkedHashMap<>();int n=r.getMetaData().getColumnCount();for(int i=1;i<=n;i++)m.put(r.getMetaData().getColumnLabel(i),r.getObject(i));return m;}}}
    private void bind(PreparedStatement p,Object... args)throws SQLException{for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);}
}
